/**
 * Layout shell (CapCut desktop): top bar, then [Library | Player | Inspector] over the Timeline.
 * Each region renders ONE component owned by a builder. Splitter sizes persist per browser.
 * Owner: architect/QA. Builders do not edit this file.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { ExportDialog } from './export/ExportDialog';
import { Inspector } from './inspector/Inspector';
import { LeftPanel } from './panels/LeftPanel';
import { Player } from './player/Player';
import { useEditor } from './store';
import { bootProject, startAutosave } from './store/autosave';
import { Timeline } from './timeline/Timeline';
import { withShortcut } from './timeline/shortcutDefs';
import { onAppEvent } from './ui/appEvents';
import { Icon } from './ui/Icon';
import { ShortcutsPanel } from './ui/ShortcutsPanel';
import { Toaster } from './ui/Toaster';

interface Sizes {
  left: number; // px
  right: number; // px
  upper: number; // fraction of the area under the top bar
}
const DEFAULT_SIZES: Sizes = { left: 0, right: 0, upper: 0.6 };
const SIZES_KEY = 'our-editor:layout';

function loadSizes(): Sizes {
  try {
    const raw = localStorage.getItem(SIZES_KEY);
    if (raw) return { ...DEFAULT_SIZES, ...(JSON.parse(raw) as Partial<Sizes>) };
  } catch {
    /* storage unavailable */
  }
  const w = typeof window !== 'undefined' ? window.innerWidth : 1600;
  return { left: Math.round(w * 0.28), right: Math.round(w * 0.25), upper: 0.6 };
}

function useDrag(onMove: (dx: number, dy: number) => void, onEnd: () => void) {
  const [dragging, setDragging] = useState(false);
  const start = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      let x = e.clientX;
      let y = e.clientY;
      setDragging(true);
      const move = (ev: PointerEvent) => {
        onMove(ev.clientX - x, ev.clientY - y);
        x = ev.clientX;
        y = ev.clientY;
      };
      const up = () => {
        setDragging(false);
        window.removeEventListener('pointermove', move);
        window.removeEventListener('pointerup', up);
        onEnd();
      };
      window.addEventListener('pointermove', move);
      window.addEventListener('pointerup', up);
    },
    [onMove, onEnd],
  );
  return { dragging, start };
}

function TopBar({ onExport, onShortcuts }: { onExport: () => void; onShortcuts: () => void }) {
  const name = useEditor((s) => s.project.name);
  const setProjectName = useEditor((s) => s.setProjectName);
  const saveStatus = useEditor((s) => s.saveStatus);
  const [draft, setDraft] = useState<string | null>(null);
  const saved = saveStatus.error
    ? `Save failed: ${saveStatus.error}`
    : saveStatus.saving
      ? 'Saving…'
      : saveStatus.lastSavedAt
        ? `Auto saved: ${new Date(saveStatus.lastSavedAt).toLocaleTimeString([], { hour12: false })}`
        : 'Not saved yet';
  return (
    <header className="topbar">
      <div className="topbar__left">{saved}</div>
      <div className="topbar__title">
        <input
          aria-label="Project name"
          value={draft ?? name}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={() => {
            if (draft !== null && draft !== name) setProjectName(draft);
            setDraft(null);
          }}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
            if (e.key === 'Escape') setDraft(null);
          }}
        />
      </div>
      <div className="topbar__right">
        <button
          className="icon-btn"
          onClick={onShortcuts}
          onMouseDown={(e) => e.preventDefault()}
          title="Keyboard shortcuts"
          aria-label="Keyboard shortcuts"
          data-testid="shortcuts-button"
        >
          <Icon name="keyboard" />
        </button>
        <button className="btn btn--primary" onClick={onExport} title={withShortcut('Export', 'export')} data-testid="export-button">
          <Icon name="export" size={14} /> Export
        </button>
      </div>
    </header>
  );
}

export default function App() {
  const [sizes, setSizes] = useState<Sizes>(loadSizes);
  const [exportOpen, setExportOpen] = useState(false);
  const [shortcutsOpen, setShortcutsOpen] = useState(false);
  const closeShortcuts = useCallback(() => setShortcutsOpen(false), []);
  const bodyRef = useRef<HTMLDivElement>(null);
  const sizesRef = useRef(sizes);
  sizesRef.current = sizes;

  useEffect(() => {
    let stop: (() => void) | undefined;
    let cancelled = false;
    void bootProject().finally(() => {
      if (!cancelled) stop = startAutosave();
    });
    return () => {
      cancelled = true;
      stop?.();
    };
  }, []);

  // ⌘E comes through the shared shortcut table (src/timeline/shortcutDefs.ts)
  useEffect(() => onAppEvent('export', () => setExportOpen(true)), []);

  const persist = useCallback(() => {
    try {
      localStorage.setItem(SIZES_KEY, JSON.stringify(sizesRef.current));
    } catch {
      /* ignore */
    }
  }, []);
  const leftDrag = useDrag(
    useCallback((dx: number) => setSizes((s) => ({ ...s, left: Math.max(240, Math.min(s.left + dx, 900)) })), []),
    persist,
  );
  const rightDrag = useDrag(
    useCallback((dx: number) => setSizes((s) => ({ ...s, right: Math.max(280, Math.min(s.right - dx, 700)) })), []),
    persist,
  );
  const upperDrag = useDrag(
    useCallback((_dx: number, dy: number) => {
      const h = bodyRef.current?.clientHeight ?? 800;
      setSizes((s) => ({ ...s, upper: Math.max(0.25, Math.min(s.upper + dy / h, 0.8)) }));
    }, []),
    persist,
  );

  return (
    <div className="app">
      <TopBar onExport={() => setExportOpen(true)} onShortcuts={() => setShortcutsOpen(true)} />
      <div ref={bodyRef} style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', gap: 'var(--gutter)' }}>
        <div className="upper" style={{ height: `${sizes.upper * 100}%` }}>
          <section className="panel" style={{ width: sizes.left, flex: 'none' }} aria-label="Library" data-testid="left-panel">
            <LeftPanel />
          </section>
          <div className={`splitter-v${leftDrag.dragging ? ' is-dragging' : ''}`} onPointerDown={leftDrag.start} />
          <section className="panel" style={{ flex: 1, minWidth: 240 }} aria-label="Player" data-testid="player">
            <Player />
          </section>
          <div className={`splitter-v${rightDrag.dragging ? ' is-dragging' : ''}`} onPointerDown={rightDrag.start} />
          <section className="panel" style={{ width: sizes.right, flex: 'none' }} aria-label="Inspector" data-testid="inspector">
            <Inspector />
          </section>
        </div>
        <div className={`splitter-h${upperDrag.dragging ? ' is-dragging' : ''}`} onPointerDown={upperDrag.start} />
        <section className="panel timeline-region" aria-label="Timeline" data-testid="timeline">
          <Timeline />
        </section>
      </div>
      {exportOpen && <ExportDialog open={exportOpen} onClose={() => setExportOpen(false)} />}
      {shortcutsOpen && <ShortcutsPanel onClose={closeShortcuts} />}
      <Toaster />
    </div>
  );
}
